def min_moves_to_sort_train(n, p):
    from bisect import bisect_left

    def longest_increasing_subsequence(arr):
        lis = []
        for x in arr:
            pos = bisect_left(lis, x)
            if pos == len(lis):
                lis.append(x)
            else:
                lis[pos] = x
        return len(lis)

    def longest_decreasing_subsequence(arr):
        lds = []
        for x in reversed(arr):
            pos = bisect_left(lds, -x)
            if pos == len(lds):
                lds.append(-x)
            else:
                lds[pos] = -x
        return len(lds)

    lis_length = longest_increasing_subsequence(p)
    lds_length = longest_decreasing_subsequence(p)

    return n - max(lis_length, lds_length)

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    p = list(map(int, data[1:n+1]))

    result = min_moves_to_sort_train(n, p)
    print(result)
